/dts-v1/;
/plugin/;

#include <zephyr/dt-bindings/pinctrl/test-pinctrl.h>

/*
 * The following nodes are for pinctrl test purposes. They are not
 * functional, but allow to test the pinctrl API.
 */

/ {
	pinctrl_test: pinctrl_test {
		compatible = "test-pinctrl";
		#pinctrl-cells = <1>;
	};
};

&pinctrl_test {
	pinctrl_test_sleep: pinctrl_test_sleep {
		test-pins = <TEST_PIN_SLEEP>;
	};

	pinctrl_test_active: pinctrl_test_active {
		test-pins = <TEST_PIN_ACTIVE>;
	};

	pinctrl_test_deep_sleep: pinctrl_test_deep_sleep {
		test-pins = <TEST_PIN_DEEP_SLEEP>;
	};

	pinctrl_test_no_pins: pinctrl_test_no_pins {
	};

	pinctrl_test_state_1: pinctrl_test_state_1 {
		test-pins = <TEST_PIN_1>;
	};

	pinctrl_test_state_2: pinctrl_test_state_2 {
		test-pins = <TEST_PIN_2>;
	};

	pinctrl_test_state_3: pinctrl_test_state_3 {
		test-pins = <TEST_PIN_3>;
	};

	pinctrl_test_state_4: pinctrl_test_state_4 {
		test-pins = <TEST_PIN_4>;
	};

	pinctrl_test_state_5: pinctrl_test_state_5 {
		test-pins = <TEST_PIN_5>;
	};

	pinctrl_test_state_6: pinctrl_test_state_6 {
		test-pins = <TEST_PIN_6>;
	};

	pinctrl_test_state_7: pinctrl_test_state_7 {
		test-pins = <TEST_PIN_7>;
	};

	pinctrl_test_state_8: pinctrl_test_state_8 {
		test-pins = <TEST_PIN_8>;
	};
};

/ {
	test_device: test_device@0 {
		compatible = "test-device";
		reg = <0x0 0x1000>;
		pinctrl-0 = <&pinctrl_test_sleep>, <&pinctrl_test_active>;
		pinctrl-1 = <&pinctrl_test_deep_sleep>;
		pinctrl-names = "default", "state_1";
	};

	test_device_no_pinctrl: test_device_no_pinctrl@1 {
		compatible = "test-device";
		reg = <0x1 0x1000>;
	};

	test_device_no_pins: test_device_no_pins@2 {
		compatible = "test-device";
		reg = <0x2 0x1000>;
		pinctrl-0 = <&pinctrl_test_no_pins>;
		pinctrl-names = "default";
	};

	test_device_multiple: test_device_multiple@3 {
		compatible = "test-device";
		reg = <0x3 0x1000>;
		pinctrl-0 = <&pinctrl_test_state_1 &pinctrl_test_state_2>;
		pinctrl-1 = <&pinctrl_test_state_3 &pinctrl_test_state_4>;
		pinctrl-2 = <&pinctrl_test_state_5 &pinctrl_test_state_6>;
		pinctrl-3 = <&pinctrl_test_state_7 &pinctrl_test_state_8>;
		pinctrl-names = "default", "state_1", "state_2", "state_3";
	};
};
